@strawberry.type
class Mutation:
    @strawberry.mutation
    def revoke_api_key(self, info: Info, key_id: int) -> OperationStatus:
        db: Session = info.context["db"]
        user = info.context["user"]
        deleted = db.query(ApiKey).filter(ApiKey.id == key_id, ApiKey.user_id == user.id).delete()
        db.commit()
        return OperationStatus(success=deleted > 0)
